 // One-car pilot, selection, refundable security deposit and driver benefits.
 let programDriverId='DRV-2';
 const programStatusLabel=status=>({pilot:'No protótipo',planned:'Planejado',later:'Etapa futura'}[status]||'Em avaliação');
 function programBenefitsCards(){return `<div class="program-benefits">${R.benefits.map(b=>`<article class="program-benefit"><span class="tag ${b.status==='pilot'?'green':''}">${programStatusLabel(b.status)}</span><h3>${esc(b.title)}</h3><p>${esc(b.description)}</p></article>`).join('')}</div>`;}
 function programView(){R.ensure(ops);const d=ops.drivers.find(d=>d.id===programDriverId)||ops.drivers[0];programDriverId=d.id;const p=ops.program.policy,a=R.assessment(ops,d.id),deposit=R.depositSummary(ops,d.id),credits=R.driverCredits(ops,d.id);return `<div class="program-workspace">${heading('PILOTO E BENEFÍCIOS','Um carro. Um padrão de operação.','Seleção por critérios objetivos, caução conferida e ganho adicional transparente para o motorista. O piloto permite validar a rotina antes de crescer.')}<div class="program-promise"><div><span class="eyebrow">ESTOQUE FINANCIADO PELA RODAVOLT</span><h2>100% da margem da lojinha<br>para quem está ao volante.</h2><p>O custo do produto recompõe o capital do estoque. Depois do acerto, a margem pertence ao motorista: receber ou usar como crédito no aluguel, sem contar duas vezes.</p></div><span class="program-profit">100%<small>DA MARGEM<br>DO MOTORISTA</small></span></div><div class="stats gap">${stat('Piloto inicial',String(p.pilotCars)+' carro(s)','Validar rotina, custos e relacionamento')}${stat('Caução exigida',cash(p.depositAmount),'Valor demonstrativo configurado para o piloto')}${stat('Decisão de seleção',a.approved?'Aprovado no exemplo':'Conferência pendente',esc(d.name))}${stat('Caução do perfil',cash(deposit.balance),deposit.remaining>0?'Falta conferir '+cash(deposit.remaining):'Exigência atendida no livro demonstrativo')}</div><form id="program-profile-form" class="program-profile gap">${select('driverId','Perfil para conferir',d.id,ops.drivers.map(d=>[d.id,d.name]))}<button type="submit" class="btn">Abrir perfil</button></form><div class="notice">Critérios precisam ser verificáveis e aplicados igualmente. Sem pontuação automática, promessa de aprovação ou bloqueio por característica pessoal. Caução, contrato, vistoria e disponibilidade são conferências separadas.</div><div class="grid2 gap">${panel('1. Seleção e regras do piloto',programAssessmentForm(d,a))}${panel('2. Caução e liberação',row('Valor exigido',cash(deposit.required))+row('Saldo de caução recebido',cash(deposit.balance),'Separado de receita, lucro e crédito da lojinha.')+row('Falta conferir',cash(deposit.remaining))+`<div class="actions gap">${btn('Registrar caução de exemplo','program-deposit','primary',`data-driver-id="${d.id}"`)}${btn('Registrar devolução','program-refund','',`data-driver-id="${d.id}" ${deposit.balance<=0?'disabled':''}`)}</div><p class="caption">O registro é uma movimentação fictícia no livro, com conta e referência. Nenhum banco foi acionado; o recebimento real exigirá confirmação e conciliação. A devolução depende de conferência contratual e das pendências do vínculo.</p>`)}</div><div class="gap">${panel('3. Ganho da loja e abatimento opcional',programCredits(d.id,false),tag('LUCRO DO MOTORISTA','green'))}</div><div class="gap">${section('Benefícios que fazem sentido para a rotina','Começar com o que podemos validar. Novos aplicativos e parcerias entram por etapas, com escopo e condições próprios.')}${programBenefitsCards()}</div><div class="notice gap">Regras de uso do carro, seguro, multas, manutenção, loja, caução e encerramento precisam ser claras e revisadas. O aplicativo organiza conferências; não oferece blindagem jurídica nem substitui revisão profissional.</div></div>`;}
 function programAssessmentForm(d,a){return `<form id="program-assessment-form"><input type="hidden" name="driverId" value="${d.id}"><p class="caption">Conferência manual de ${esc(d.name)}. Os documentos ficam fora deste protótipo.</p>${R.criteria.map(([key,label])=>`<label class="check"><input type="checkbox" name="criterion-${key}" ${a.checks?.[key]?'checked':''}>${esc(label)}</label>`).join('')}<label class="field gap">Registro objetivo da conferência<textarea name="note" rows="3" maxlength="1000" placeholder="O que foi conferido, o que falta e a próxima ação. Sem dados ou documentos pessoais.">${esc(a.note||'')}</textarea></label><div class="gap">${select('approved','Decisão manual',a.approved?'yes':'hold',[['hold','Manter em conferência'],['yes','Aprovar no piloto demonstrativo']])}</div><div class="form-actions"><button type="submit" class="btn primary">Salvar conferência e decisão</button></div><p class="caption">Aprovar exige todos os critérios conferidos. Ainda são necessários caução, contrato, vistoria e carro disponível para a entrega.</p></form>`;}
 function programCredits(driverId,forDriver=false){const summary=R.driverCredits(ops,driverId),records=summary.records||ops.program.credits.filter(c=>c.driverId===driverId),charges=ops.charges.filter(c=>c.driverId===driverId&&c.status!=='paid');return row('Margem gerada e conferida',cash(summary.earned),'Margem = venda menos custo do produto. O estoque é financiado pela RODAVOLT.')+row('Crédito disponível',cash(summary.available),'Somente após o acerto da loja; a venda em aberto ainda não é crédito.')+row('Usado no aluguel',cash(summary.applied),'Abatimento registrado na cobrança, sem um segundo pagamento do mesmo ganho.')+row('Pago ao motorista',cash(summary.paid),'Valores já pagos não podem virar desconto novamente.')+(records.length?table(['Crédito','Margem','Usado no aluguel','Pago'],records.map(c=>`<tr><td>${esc(c.id)}</td><td>${cash(c.amount)}</td><td>${cash(c.applied||0)}</td><td>${cash(c.paid||0)}</td></tr>`).join('')):'<p class="caption gap">Ainda não há margem de venda conferida para este perfil.</p>')+(summary.available>0&&charges.length?`<div class="actions gap">${btn(forDriver?'Escolher crédito para meu aluguel':'Aplicar crédito no aluguel','program-credit','primary',`data-driver-id="${driverId}"`)}</div>`:'')+`<p class="caption gap">Abatimento é opcional. Receber o cliente, acertar o estoque, gerar crédito e usar no aluguel são etapas diferentes. Se o motorista ficar com a margem em dinheiro, ela precisa ser registrada como paga para não gerar um novo crédito.</p>`;}
 function driverBenefits(){const d=driverProfile();R.ensure(ops);const a=R.assessment(ops,d.id),deposit=R.depositSummary(ops,d.id);return `<div class="program-driver"><section class="program-promise"><div><span class="eyebrow">SEU ESFORÇO, SEU GANHO</span><h2>A margem da lojinha<br>é toda sua.</h2><p>A RODAVOLT fornece o capital dos produtos. Depois de conferir as vendas e recompor o custo, 100% da margem fica para você.</p></div></section><div class="gap">${panel('Seu crédito, com transparência',programCredits(d.id,true))}</div><div class="gap">${panel('Seu acesso ao piloto',row('Conferência da seleção',a.approved?'Aprovada no exemplo':'Em conferência')+row('Caução exigida',cash(deposit.required))+row('Saldo de caução conferido',cash(deposit.balance),'Dinheiro separado de aluguel, receita e ganho da loja.')+row('Falta conferir',cash(deposit.remaining))+`<p class="caption">Caução não é desconto na semana nem crédito de consumo. A devolução segue o contrato e a conferência de pendências; o aplicativo não faz retenções automáticas.</p>`+btn('Ver minha contratação','driver-onboarding'))}</div><div class="gap">${section('Seus benefícios e próximos passos','O que já pode ser explorado no protótipo e o que ainda depende de implementação ou parceria.')}${programBenefitsCards()}</div><div class="notice gap">Nenhuma parceria externa ou acesso a outro aplicativo é ativado aqui. As condições serão apresentadas antes de qualquer adesão.</div></div>`;}
 function programDepositForm(driverId,refund=false){R.ensure(ops);const d=M.driver(ops,driverId),s=R.depositSummary(ops,driverId),accounts=ops.finance?.accounts||[];return `<form id="program-deposit-form"><input type="hidden" name="driverId" value="${d.id}"><input type="hidden" name="operation" value="${refund?'refund':'receipt'}"><div class="notice">Registro fictício de ${refund?'devolução':'recebimento'} de caução. Nenhum pagamento é feito e nenhum banco é acionado.</div><div class="gap">${row('Motorista',esc(d.name))}${row('Saldo de caução conferido',cash(s.balance))}</div><div class="fields gap">${input('amount',refund?'Valor a devolver · R$':'Valor recebido no exemplo · R$',refund?s.balance:s.remaining||s.required,`type="number" min="0.01" step="0.01" required ${refund?'max="'+s.balance+'"':''}`)}${input('date','Data do registro',K.operatingDate,'type="date" required')}${select('accountId','Conta do livro demonstrativo',accounts[0]?.id||'',accounts.map(a=>[a.id,a.name]))}${input('reference','Referência única e motivo','','required maxlength="150" placeholder="Ex.: CAU-DEMO-002 · caução fictícia conferida"')}</div><label class="check gap"><input type="checkbox" name="confirm" required>Estou registrando um exemplo, sem transação bancária real</label><div class="form-actions"><button type="submit" class="btn primary">${refund?'Registrar devolução de exemplo':'Registrar caução de exemplo'}</button></div><p class="caption">Caução entra como obrigação da locadora perante o motorista; não é faturamento nem lucro.</p></form>`;}
 function programCreditForm(driverId){R.ensure(ops);const d=M.driver(ops,driverId),summary=R.driverCredits(ops,driverId),records=(summary.records||ops.program.credits.filter(c=>c.driverId===driverId)).filter(c=>c.available===undefined||c.available>0),charges=ops.charges.filter(c=>c.driverId===driverId&&c.status!=='paid');return `<form id="program-credit-form"><input type="hidden" name="driverId" value="${driverId}">${row('Motorista',esc(d.name))}${row('Crédito disponível',cash(summary.available))}<div class="notice gap">Escolha um crédito de margem já conferida. O abatimento usa até o saldo da cobrança e preserva eventual sobra do crédito.</div><div class="fields gap">${select('creditId','Crédito da lojinha',records[0]?.id||'',records.map(c=>[c.id,c.id+' · disponível '+cash(c.available??c.amount)]))}${select('chargeId','Aluguel para abater',charges[0]?.id||'',charges.map(c=>[c.id,c.id+' · '+date(c.date)+' · saldo '+cash(R.currentChargeBalance(ops,c))]))}</div><label class="check gap"><input type="checkbox" name="confirm" required>Quero aplicar este crédito no aluguel e conferir os valores registrados</label><div class="form-actions"><button type="submit" class="btn primary" ${summary.available<=0||!charges.length?'disabled':''}>Registrar abatimento demonstrativo</button></div><p class="caption">O mesmo ganho não pode ser pago em dinheiro e usado novamente como desconto. Não realiza transferência bancária.</p></form>`;}
 function programAction(action,e){if(!action.startsWith('program-'))return false;R.ensure(ops);
  if(action==='program-open'){open('Piloto e benefícios',programView());return true;}
  if(action==='program-deposit'||action==='program-refund'){programDriverId=e.dataset.driverId;open(action==='program-refund'?'Devolução de caução · exemplo':'Conferir caução · exemplo',programDepositForm(programDriverId,action==='program-refund'));return true;}
  if(action==='program-credit'){const id=e.dataset.driverId;if(mode==='driver'&&id!==activeDriverId)throw new RangeError('O crédito precisa pertencer ao perfil atual.');programDriverId=id;open('Crédito da loja no aluguel',programCreditForm(id));return true;}
  return false;
 }
 function programSubmit(form,f){if(!form.id.startsWith('program-'))return false;const id=String(f.get('driverId')||programDriverId);R.ensure(ops);
  if(form.id==='program-profile-form'){M.driver(ops,id);programDriverId=id;open('Piloto e benefícios',programView());return true;}
  if(form.id==='program-assessment-form'){R.reviewCandidate(ops,id,{checks:Object.fromEntries(R.criteria.map(([key])=>[key,f.has('criterion-'+key)])),note:String(f.get('note')||''),approved:f.get('approved')==='yes'});}
  else if(form.id==='program-deposit-form'){if(!f.has('confirm'))throw new RangeError('Confirme que o registro é demonstrativo.');const input={amount:Number(f.get('amount')),date:String(f.get('date')),reference:String(f.get('reference')),accountId:String(f.get('accountId'))};if(f.get('operation')==='refund')R.refundDeposit(ops,id,input);else R.recordDeposit(ops,id,input);}
  else if(form.id==='program-credit-form'){if(mode==='driver'&&id!==activeDriverId)throw new RangeError('Crédito fora do perfil atual.');if(!f.has('confirm'))throw new RangeError('Confirme a aplicação do crédito.');const credit=ops.program.credits.find(c=>c.id===f.get('creditId')),charge=ops.charges.find(c=>c.id===f.get('chargeId'));if(!credit||credit.driverId!==id||!charge||charge.driverId!==id)throw new RangeError('Crédito e cobrança precisam ser do mesmo motorista.');R.applyCredit(ops,credit.id,charge.id);}
  else return false;
  programDriverId=id;persist();close();render();if(mode==='admin')open('Piloto e benefícios',programView());toast('Conferência registrada no piloto demonstrativo.');return true;
 }
